-- ===========================================================================
-- 20261015122524_initial_schema.sql
-- ===========================================================================

-- Sleek Connect: catalogue, checkout configuration and orders.
--
-- Access model
--   * Catalogue and checkout-configuration tables are readable by everyone (anon + authenticated).
--     Nothing in them is writable through the Data API; manage them from the dashboard or with
--     the service role.
--   * Orders are only created through public.place_order(), which prices every line from the
--     database. Shoppers who are signed in can read their own orders; nobody else can.

-- ---------------------------------------------------------------------------
-- Types
-- ---------------------------------------------------------------------------

create type public.department as enum ('beauty', 'kids');
create type public.product_kind as enum ('bottle', 'jar', 'tube', 'garment', 'toy', 'gift');
create type public.kids_filter as enum ('bath', 'toys', 'clothing', 'gifts');
create type public.order_status as enum (
  'pending_payment', 'paid', 'packed', 'out_for_delivery', 'delivered', 'cancelled'
);
create type public.payment_method as enum ('momo', 'card');
create type public.momo_network as enum ('mtn', 'telecel', 'at');

-- ---------------------------------------------------------------------------
-- Catalogue
-- ---------------------------------------------------------------------------

create table public.age_bands (
  id text primary key,
  label text not null,
  stage text not null,
  sort_order smallint not null
);

comment on table public.age_bands is
  'Child age bands used only as a shopping filter. No child data is stored (PRD FR-016).';

create table public.categories (
  id text primary key,
  name text not null,
  department public.department not null,
  image_key text,
  tint text not null,
  kind public.product_kind not null,
  sort_order smallint not null default 0
);

create table public.products (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name text not null,
  brand text,
  department public.department not null,
  category_id text references public.categories (id) on update cascade on delete set null,
  kids_filter public.kids_filter,
  collection text,
  price_ghs numeric(10, 2) not null check (price_ghs >= 0),
  was_price_ghs numeric(10, 2) check (was_price_ghs >= 0),
  badge text,
  tag text not null,
  summary text not null,
  image_key text,
  tint text not null,
  kind public.product_kind not null,
  -- Product-page content: description, highlights, freeFrom, recommendedAge, warnings, howToUse, gallery.
  details jsonb check (details is null or jsonb_typeof(details) = 'object'),
  is_published boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index products_category_id_idx on public.products (category_id);

create table public.product_sizes (
  product_id uuid not null references public.products (id) on delete cascade,
  code text not null,
  label text not null,
  price_ghs numeric(10, 2) not null check (price_ghs >= 0),
  is_default boolean not null default false,
  sort_order smallint not null default 0,
  primary key (product_id, code)
);

create unique index product_sizes_one_default_idx on public.product_sizes (product_id) where is_default;

create table public.product_age_bands (
  product_id uuid not null references public.products (id) on delete cascade,
  age_band_id text not null references public.age_bands (id) on update cascade on delete cascade,
  primary key (product_id, age_band_id)
);

create index product_age_bands_age_band_id_idx on public.product_age_bands (age_band_id);

-- Ordered product lists shown on the storefront, e.g. 'home_new_arrivals' (PRD FR-010).
create table public.merchandising_slots (
  slot text not null,
  product_id uuid not null references public.products (id) on delete cascade,
  position smallint not null,
  primary key (slot, product_id)
);

create index merchandising_slots_product_id_idx on public.merchandising_slots (product_id);

-- ---------------------------------------------------------------------------
-- Checkout configuration
-- ---------------------------------------------------------------------------

create table public.delivery_areas (
  name text primary key,
  is_active boolean not null default true,
  sort_order smallint not null default 0
);

create table public.delivery_options (
  id text primary key,
  label text not null,
  -- NULL until the business sets the fee; orders then have no total yet.
  fee_ghs numeric(10, 2) check (fee_ghs >= 0),
  sort_order smallint not null default 0
);

-- ---------------------------------------------------------------------------
-- Orders
-- ---------------------------------------------------------------------------

create sequence public.order_number_seq start 1001;

create table public.orders (
  id uuid primary key default gen_random_uuid(),
  order_number text not null unique default ('SC-' || nextval('public.order_number_seq')),
  status public.order_status not null default 'pending_payment',
  user_id uuid references auth.users (id) on delete set null,
  customer_name text not null,
  phone text not null,
  area text not null references public.delivery_areas (name) on update cascade,
  ghanapost_gps text,
  rider_directions text,
  delivery_option_id text not null references public.delivery_options (id),
  is_gift boolean not null default false,
  payment_method public.payment_method not null,
  momo_network public.momo_network,
  wallet_number text,
  subtotal_ghs numeric(10, 2) not null check (subtotal_ghs >= 0),
  delivery_fee_ghs numeric(10, 2) check (delivery_fee_ghs >= 0),
  total_ghs numeric(10, 2) check (total_ghs >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint orders_momo_details check (
    payment_method <> 'momo' or (momo_network is not null and wallet_number is not null)
  )
);

create index orders_user_id_idx on public.orders (user_id);
create index orders_area_idx on public.orders (area);
create index orders_delivery_option_id_idx on public.orders (delivery_option_id);

create table public.order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders (id) on delete cascade,
  product_id uuid references public.products (id) on delete set null,
  -- Snapshot of what was bought, so the order stays correct if the catalogue changes.
  product_name text not null,
  size_code text,
  size_label text,
  unit_price_ghs numeric(10, 2) not null check (unit_price_ghs >= 0),
  quantity integer not null check (quantity between 1 and 20),
  line_total_ghs numeric(10, 2) not null check (line_total_ghs >= 0)
);

create index order_items_order_id_idx on public.order_items (order_id);
create index order_items_product_id_idx on public.order_items (product_id);

-- ---------------------------------------------------------------------------
-- updated_at maintenance
-- ---------------------------------------------------------------------------

create function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger products_set_updated_at
  before update on public.products
  for each row execute function public.set_updated_at();

create trigger orders_set_updated_at
  before update on public.orders
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Row level security
-- ---------------------------------------------------------------------------

alter table public.age_bands enable row level security;
alter table public.categories enable row level security;
alter table public.products enable row level security;
alter table public.product_sizes enable row level security;
alter table public.product_age_bands enable row level security;
alter table public.merchandising_slots enable row level security;
alter table public.delivery_areas enable row level security;
alter table public.delivery_options enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;

create policy "Age bands are public" on public.age_bands
  for select to anon, authenticated using (true);

create policy "Categories are public" on public.categories
  for select to anon, authenticated using (true);

create policy "Published products are public" on public.products
  for select to anon, authenticated using (is_published);

create policy "Sizes of published products are public" on public.product_sizes
  for select to anon, authenticated
  using (exists (select 1 from public.products p where p.id = product_id and p.is_published));

create policy "Age bands of published products are public" on public.product_age_bands
  for select to anon, authenticated
  using (exists (select 1 from public.products p where p.id = product_id and p.is_published));

create policy "Merchandising of published products is public" on public.merchandising_slots
  for select to anon, authenticated
  using (exists (select 1 from public.products p where p.id = product_id and p.is_published));

create policy "Active delivery areas are public" on public.delivery_areas
  for select to anon, authenticated using (is_active);

create policy "Delivery options are public" on public.delivery_options
  for select to anon, authenticated using (true);

create policy "Shoppers can read their own orders" on public.orders
  for select to authenticated using (user_id = (select auth.uid()));

create policy "Shoppers can read items of their own orders" on public.order_items
  for select to authenticated
  using (exists (select 1 from public.orders o where o.id = order_id and o.user_id = (select auth.uid())));

-- Explicit grants: read-only catalogue for the Data API; no direct access to orders for anon.
revoke all on public.orders, public.order_items from anon;
grant select on
  public.age_bands, public.categories, public.products, public.product_sizes, public.product_age_bands,
  public.merchandising_slots, public.delivery_areas, public.delivery_options
  to anon, authenticated;
grant select on public.orders, public.order_items to authenticated;

-- ---------------------------------------------------------------------------
-- place_order: the only way to create an order
-- ---------------------------------------------------------------------------

-- p_customer: {"name", "phone", "area", "ghanapost_gps"?, "directions"?}
-- p_payment:  {"method": "momo"|"card", "network"?: "mtn"|"telecel"|"at", "wallet"?}
-- p_items:    [{"slug", "size"?, "quantity"}]
create function public.place_order(
  p_customer jsonb,
  p_delivery_option text,
  p_payment jsonb,
  p_items jsonb,
  p_is_gift boolean default false
)
returns table (
  order_number text,
  subtotal_ghs numeric,
  delivery_fee_ghs numeric,
  total_ghs numeric
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_name text := nullif(btrim(p_customer ->> 'name'), '');
  v_phone text := nullif(btrim(p_customer ->> 'phone'), '');
  v_area text := nullif(btrim(p_customer ->> 'area'), '');
  v_method text := p_payment ->> 'method';
  v_network text := nullif(p_payment ->> 'network', '');
  v_wallet text := nullif(btrim(p_payment ->> 'wallet'), '');
  v_fee numeric(10, 2);
  v_order_id uuid;
  v_order_number text;
  v_subtotal numeric(10, 2) := 0;
  v_item jsonb;
  v_product public.products%rowtype;
  v_size public.product_sizes%rowtype;
  v_has_sizes boolean;
  v_qty integer;
  v_unit numeric(10, 2);
begin
  if v_name is null or length(v_name) > 120 then
    raise exception 'Enter your full name.' using errcode = '22023';
  end if;

  if v_phone is null or regexp_replace(v_phone, '\D', '', 'g') !~ '^\d{9,15}$' then
    raise exception 'Enter a valid phone number.' using errcode = '22023';
  end if;

  if not exists (select 1 from public.delivery_areas a where a.name = v_area and a.is_active) then
    raise exception 'We don''t deliver to that area yet.' using errcode = '22023';
  end if;

  select o.fee_ghs into v_fee from public.delivery_options o where o.id = p_delivery_option;
  if not found then
    raise exception 'Choose a delivery window.' using errcode = '22023';
  end if;

  if v_method is null or v_method not in ('momo', 'card') then
    raise exception 'Choose a payment method.' using errcode = '22023';
  end if;

  if v_method = 'momo' then
    if v_network is null or v_network not in ('mtn', 'telecel', 'at') then
      raise exception 'Choose your Mobile Money network.' using errcode = '22023';
    end if;
    if v_wallet is null or regexp_replace(v_wallet, '\D', '', 'g') !~ '^\d{9,15}$' then
      raise exception 'Enter a valid wallet number.' using errcode = '22023';
    end if;
  else
    v_network := null;
    v_wallet := null;
  end if;

  if jsonb_typeof(p_items) is distinct from 'array'
     or jsonb_array_length(p_items) = 0
     or jsonb_array_length(p_items) > 50 then
    raise exception 'Your bag is empty.' using errcode = '22023';
  end if;

  insert into public.orders (
    user_id, customer_name, phone, area, ghanapost_gps, rider_directions, delivery_option_id,
    is_gift, payment_method, momo_network, wallet_number, subtotal_ghs
  )
  values (
    auth.uid(), v_name, v_phone, v_area,
    left(nullif(btrim(p_customer ->> 'ghanapost_gps'), ''), 20),
    left(nullif(btrim(p_customer ->> 'directions'), ''), 300),
    p_delivery_option, coalesce(p_is_gift, false), v_method::public.payment_method,
    v_network::public.momo_network, v_wallet, 0
  )
  returning id, orders.order_number into v_order_id, v_order_number;

  for v_item in select value from jsonb_array_elements(p_items) loop
    select * into v_product
    from public.products p
    where p.slug = v_item ->> 'slug' and p.is_published;
    if not found then
      raise exception 'A product in your bag is no longer available.' using errcode = '22023';
    end if;

    if jsonb_typeof(v_item -> 'quantity') is distinct from 'number'
       or (v_item ->> 'quantity')::numeric <> trunc((v_item ->> 'quantity')::numeric)
       or (v_item ->> 'quantity')::numeric not between 1 and 20 then
      raise exception 'Quantities must be between 1 and 20.' using errcode = '22023';
    end if;
    v_qty := (v_item ->> 'quantity')::integer;

    v_size := null;
    select exists (select 1 from public.product_sizes s where s.product_id = v_product.id) into v_has_sizes;
    if v_has_sizes then
      select * into v_size
      from public.product_sizes s
      where s.product_id = v_product.id
        and (s.code = v_item ->> 'size' or (v_item ->> 'size' is null and s.is_default));
      if not found then
        raise exception 'Choose a size for %.', v_product.name using errcode = '22023';
      end if;
    end if;

    v_unit := coalesce(v_size.price_ghs, v_product.price_ghs);
    v_subtotal := v_subtotal + v_unit * v_qty;

    insert into public.order_items (
      order_id, product_id, product_name, size_code, size_label, unit_price_ghs, quantity, line_total_ghs
    )
    values (
      v_order_id, v_product.id, v_product.name, v_size.code, v_size.label, v_unit, v_qty, v_unit * v_qty
    );
  end loop;

  update public.orders o
  set subtotal_ghs = v_subtotal,
      delivery_fee_ghs = v_fee,
      total_ghs = case when v_fee is null then null else v_subtotal + v_fee end
  where o.id = v_order_id;

  return query
  select v_order_number, v_subtotal, v_fee, case when v_fee is null then null else v_subtotal + v_fee end;
end;
$$;

comment on function public.place_order(jsonb, text, jsonb, jsonb, boolean) is
  'Creates a pending_payment order. Prices come from the catalogue, never from the caller.';

revoke all on function public.place_order(jsonb, text, jsonb, jsonb, boolean) from public;
grant execute on function public.place_order(jsonb, text, jsonb, jsonb, boolean) to anon, authenticated;

-- ===========================================================================
-- 20261015141808_stock_payments_accounts.sql
-- ===========================================================================

-- Stock reservation (PRD FR-025), server-verified payments (FR-031/032) and account-saved bags (FR-020).

-- ---------------------------------------------------------------------------
-- Store settings
-- ---------------------------------------------------------------------------

create table public.store_settings (
  id boolean primary key default true check (id),
  -- How long stock is held for an unpaid order before it is released.
  reservation_minutes integer not null default 15 check (reservation_minutes between 1 and 240)
);

insert into public.store_settings default values;

alter table public.store_settings enable row level security;
create policy "Store settings are public" on public.store_settings for select to anon, authenticated using (true);
grant select on public.store_settings to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Inventory
-- ---------------------------------------------------------------------------

create table public.inventory_levels (
  product_id uuid not null references public.products (id) on delete cascade,
  -- product_sizes.code, or '' for products sold in one size.
  size_code text not null default '',
  on_hand integer not null default 0 check (on_hand >= 0),
  reserved integer not null default 0 check (reserved >= 0),
  in_stock boolean generated always as (on_hand - reserved > 0) stored,
  updated_at timestamptz not null default now(),
  primary key (product_id, size_code),
  constraint inventory_reserved_within_on_hand check (reserved <= on_hand)
);

comment on table public.inventory_levels is
  'Stock per sellable unit. A unit with no row cannot be sold. reserved = held by unpaid orders.';

create trigger inventory_levels_set_updated_at
  before update on public.inventory_levels
  for each row execute function public.set_updated_at();

alter table public.inventory_levels enable row level security;

create policy "Stock status of published products is public" on public.inventory_levels
  for select to anon, authenticated
  using (exists (select 1 from public.products p where p.id = product_id and p.is_published));

-- Shoppers may see whether something is in stock, not how many units there are.
revoke all on public.inventory_levels from anon, authenticated;
grant select (product_id, size_code, in_stock) on public.inventory_levels to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Orders: reservation and lookup
-- ---------------------------------------------------------------------------

alter table public.orders
  add column reservation_expires_at timestamptz,
  add column paid_at timestamptz,
  add column cancel_reason text,
  -- Unguessable token that lets the shopper who placed a guest order check its status.
  add column public_token uuid not null default gen_random_uuid(),
  -- Set when something needs staff attention, e.g. money received for an order that already expired.
  add column needs_review boolean not null default false;

create unique index orders_public_token_idx on public.orders (public_token);
create index orders_pending_expiry_idx on public.orders (reservation_expires_at) where status = 'pending_payment';

-- ---------------------------------------------------------------------------
-- Payments
-- ---------------------------------------------------------------------------

create type public.payment_status as enum ('pending', 'succeeded', 'failed', 'expired');

create table public.payments (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders (id) on delete cascade,
  provider text not null,
  provider_reference text not null,
  amount_ghs numeric(10, 2) not null check (amount_ghs > 0),
  status public.payment_status not null default 'pending',
  last_event jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (provider, provider_reference)
);

create index payments_order_id_idx on public.payments (order_id);

create trigger payments_set_updated_at
  before update on public.payments
  for each row execute function public.set_updated_at();

-- Server-only: written by the payment functions below, read by staff in the dashboard.
alter table public.payments enable row level security;
revoke all on public.payments from anon, authenticated;

-- ---------------------------------------------------------------------------
-- Stock helpers (not callable through the API)
-- ---------------------------------------------------------------------------

-- Releases an unpaid order's reserved stock and closes the order.
create function public.release_order_reservation(p_order_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.orders o
  set status = 'cancelled', cancel_reason = p_reason
  where o.id = p_order_id and o.status = 'pending_payment';
  if not found then
    return;
  end if;

  update public.inventory_levels i
  set reserved = i.reserved - held.quantity
  from (
    select oi.product_id, coalesce(oi.size_code, '') as size_code, sum(oi.quantity)::integer as quantity
    from public.order_items oi
    where oi.order_id = p_order_id and oi.product_id is not null
    group by oi.product_id, coalesce(oi.size_code, '')
  ) held
  where i.product_id = held.product_id and i.size_code = held.size_code;

  update public.payments p set status = 'expired' where p.order_id = p_order_id and p.status = 'pending';
end;
$$;

revoke all on function public.release_order_reservation(uuid, text) from public, anon, authenticated;

-- Cancels unpaid orders whose reservation has run out. Runs every minute (see cron schedule below).
create function public.expire_unpaid_orders()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order_id uuid;
  v_count integer := 0;
begin
  for v_order_id in
    select o.id from public.orders o
    where o.status = 'pending_payment' and o.reservation_expires_at < now()
    for update skip locked
  loop
    perform public.release_order_reservation(v_order_id, 'payment_timeout');
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;

revoke all on function public.expire_unpaid_orders() from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- place_order: now reserves stock
-- ---------------------------------------------------------------------------

drop function public.place_order(jsonb, text, jsonb, jsonb, boolean);

-- p_customer: {"name", "phone", "area", "ghanapost_gps"?, "directions"?}
-- p_payment:  {"method": "momo"|"card", "network"?: "mtn"|"telecel"|"at", "wallet"?}
-- p_items:    [{"slug", "size"?, "quantity"}]
create function public.place_order(
  p_customer jsonb,
  p_delivery_option text,
  p_payment jsonb,
  p_items jsonb,
  p_is_gift boolean default false
)
returns table (
  order_number text,
  order_token uuid,
  subtotal_ghs numeric,
  delivery_fee_ghs numeric,
  total_ghs numeric,
  reserved_until timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_name text := nullif(btrim(p_customer ->> 'name'), '');
  v_phone text := nullif(btrim(p_customer ->> 'phone'), '');
  v_area text := nullif(btrim(p_customer ->> 'area'), '');
  v_method text := p_payment ->> 'method';
  v_network text := nullif(p_payment ->> 'network', '');
  v_wallet text := nullif(btrim(p_payment ->> 'wallet'), '');
  v_fee numeric(10, 2);
  v_order_id uuid;
  v_order_number text;
  v_order_token uuid;
  v_reserved_until timestamptz;
  v_subtotal numeric(10, 2) := 0;
  v_item jsonb;
  v_product public.products%rowtype;
  v_size public.product_sizes%rowtype;
  v_has_sizes boolean;
  v_qty integer;
  v_unit numeric(10, 2);
  v_available integer;
begin
  if v_name is null or length(v_name) > 120 then
    raise exception 'Enter your full name.' using errcode = '22023';
  end if;

  if v_phone is null or regexp_replace(v_phone, '\D', '', 'g') !~ '^\d{9,15}$' then
    raise exception 'Enter a valid phone number.' using errcode = '22023';
  end if;

  if not exists (select 1 from public.delivery_areas a where a.name = v_area and a.is_active) then
    raise exception 'We don''t deliver to that area yet.' using errcode = '22023';
  end if;

  select o.fee_ghs into v_fee from public.delivery_options o where o.id = p_delivery_option;
  if not found then
    raise exception 'Choose a delivery window.' using errcode = '22023';
  end if;

  if v_method is null or v_method not in ('momo', 'card') then
    raise exception 'Choose a payment method.' using errcode = '22023';
  end if;

  if v_method = 'momo' then
    if v_network is null or v_network not in ('mtn', 'telecel', 'at') then
      raise exception 'Choose your Mobile Money network.' using errcode = '22023';
    end if;
    if v_wallet is null or regexp_replace(v_wallet, '\D', '', 'g') !~ '^\d{9,15}$' then
      raise exception 'Enter a valid wallet number.' using errcode = '22023';
    end if;
  else
    v_network := null;
    v_wallet := null;
  end if;

  if jsonb_typeof(p_items) is distinct from 'array'
     or jsonb_array_length(p_items) = 0
     or jsonb_array_length(p_items) > 50 then
    raise exception 'Your bag is empty.' using errcode = '22023';
  end if;

  select now() + make_interval(mins => s.reservation_minutes) into v_reserved_until from public.store_settings s;

  insert into public.orders (
    user_id, customer_name, phone, area, ghanapost_gps, rider_directions, delivery_option_id,
    is_gift, payment_method, momo_network, wallet_number, subtotal_ghs, reservation_expires_at
  )
  values (
    auth.uid(), v_name, v_phone, v_area,
    left(nullif(btrim(p_customer ->> 'ghanapost_gps'), ''), 20),
    left(nullif(btrim(p_customer ->> 'directions'), ''), 300),
    p_delivery_option, coalesce(p_is_gift, false), v_method::public.payment_method,
    v_network::public.momo_network, v_wallet, 0, v_reserved_until
  )
  returning id, orders.order_number, orders.public_token into v_order_id, v_order_number, v_order_token;

  for v_item in select value from jsonb_array_elements(p_items) loop
    select * into v_product
    from public.products p
    where p.slug = v_item ->> 'slug' and p.is_published;
    if not found then
      raise exception 'A product in your bag is no longer available.' using errcode = '22023';
    end if;

    if jsonb_typeof(v_item -> 'quantity') is distinct from 'number'
       or (v_item ->> 'quantity')::numeric <> trunc((v_item ->> 'quantity')::numeric)
       or (v_item ->> 'quantity')::numeric not between 1 and 20 then
      raise exception 'Quantities must be between 1 and 20.' using errcode = '22023';
    end if;
    v_qty := (v_item ->> 'quantity')::integer;

    v_size := null;
    select exists (select 1 from public.product_sizes s where s.product_id = v_product.id) into v_has_sizes;
    if v_has_sizes then
      select * into v_size
      from public.product_sizes s
      where s.product_id = v_product.id
        and (s.code = v_item ->> 'size' or (v_item ->> 'size' is null and s.is_default));
      if not found then
        raise exception 'Choose a size for %.', v_product.name using errcode = '22023';
      end if;
    end if;

    -- Reserve stock. The row lock makes concurrent checkouts queue here, so stock can't be oversold.
    update public.inventory_levels i
    set reserved = i.reserved + v_qty
    where i.product_id = v_product.id
      and i.size_code = coalesce(v_size.code, '')
      and i.on_hand - i.reserved >= v_qty;
    if not found then
      select i.on_hand - i.reserved into v_available
      from public.inventory_levels i
      where i.product_id = v_product.id and i.size_code = coalesce(v_size.code, '');
      if coalesce(v_available, 0) <= 0 then
        raise exception '% is sold out.', concat_ws(', ', v_product.name, v_size.label) using errcode = '22023';
      end if;
      raise exception 'Only % left of %.', v_available, concat_ws(', ', v_product.name, v_size.label)
        using errcode = '22023';
    end if;

    v_unit := coalesce(v_size.price_ghs, v_product.price_ghs);
    v_subtotal := v_subtotal + v_unit * v_qty;

    insert into public.order_items (
      order_id, product_id, product_name, size_code, size_label, unit_price_ghs, quantity, line_total_ghs
    )
    values (
      v_order_id, v_product.id, v_product.name, v_size.code, v_size.label, v_unit, v_qty, v_unit * v_qty
    );
  end loop;

  update public.orders o
  set subtotal_ghs = v_subtotal,
      delivery_fee_ghs = v_fee,
      total_ghs = case when v_fee is null then null else v_subtotal + v_fee end
  where o.id = v_order_id;

  return query
  select v_order_number, v_order_token, v_subtotal, v_fee,
         case when v_fee is null then null else v_subtotal + v_fee end, v_reserved_until;
end;
$$;

comment on function public.place_order(jsonb, text, jsonb, jsonb, boolean) is
  'Creates a pending_payment order and reserves its stock. Prices come from the catalogue, never from the caller.';

revoke all on function public.place_order(jsonb, text, jsonb, jsonb, boolean) from public;
grant execute on function public.place_order(jsonb, text, jsonb, jsonb, boolean) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Order status for the shopper who placed it
-- ---------------------------------------------------------------------------

create function public.get_order_status(p_order_token uuid)
returns table (
  order_number text,
  status public.order_status,
  payment_status public.payment_status,
  total_ghs numeric,
  reserved_until timestamptz
)
language sql
stable
security definer
set search_path = ''
as $$
  select o.order_number, o.status,
         (select p.status from public.payments p where p.order_id = o.id order by p.created_at desc limit 1),
         o.total_ghs, o.reservation_expires_at
  from public.orders o
  where o.public_token = p_order_token;
$$;

revoke all on function public.get_order_status(uuid) from public;
grant execute on function public.get_order_status(uuid) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Payment lifecycle (server-only: called with the secret key by the web app's payment code)
-- ---------------------------------------------------------------------------

-- Records that a payment request was sent to the provider for an order.
create function public.start_payment(p_order_token uuid, p_provider text, p_reference text)
returns numeric
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders%rowtype;
begin
  select * into v_order from public.orders o where o.public_token = p_order_token for update;
  if not found then
    raise exception 'Order not found.' using errcode = '22023';
  end if;
  if v_order.status <> 'pending_payment' or v_order.reservation_expires_at < now() then
    raise exception 'This order can no longer be paid.' using errcode = '22023';
  end if;
  if v_order.total_ghs is null then
    raise exception 'Delivery fees are not set, so the order total is unknown.' using errcode = '22023';
  end if;

  insert into public.payments (order_id, provider, provider_reference, amount_ghs)
  values (v_order.id, p_provider, p_reference, v_order.total_ghs);
  return v_order.total_ghs;
end;
$$;

revoke all on function public.start_payment(uuid, text, text) from public, anon, authenticated;

-- Applies a verified provider result. Safe to call more than once for the same payment.
create function public.confirm_payment(
  p_provider text,
  p_reference text,
  p_status text,
  p_amount_ghs numeric,
  p_event jsonb default null
)
returns table (order_number text, order_status public.order_status, payment_status public.payment_status)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payment public.payments%rowtype;
  v_order public.orders%rowtype;
begin
  if p_status not in ('succeeded', 'failed') then
    raise exception 'Unknown payment status %.', p_status using errcode = '22023';
  end if;

  select * into v_payment from public.payments p
  where p.provider = p_provider and p.provider_reference = p_reference
  for update;
  if not found then
    raise exception 'Unknown payment %.', p_reference using errcode = '22023';
  end if;

  select * into v_order from public.orders o where o.id = v_payment.order_id for update;

  -- Final states are final: repeated or out-of-order notifications change nothing.
  if v_payment.status in ('succeeded', 'failed') then
    return query select v_order.order_number, v_order.status, v_payment.status;
    return;
  end if;

  update public.payments p
  set status = p_status::public.payment_status, last_event = p_event
  where p.id = v_payment.id;

  if p_status = 'failed' then
    perform public.release_order_reservation(v_order.id, 'payment_failed');
  elsif p_amount_ghs is distinct from v_payment.amount_ghs then
    -- Money arrived but not the amount we asked for: leave the order for staff to resolve.
    update public.orders o set needs_review = true where o.id = v_order.id;
  elsif v_order.status = 'pending_payment' then
    -- Turn the reservation into a sale.
    update public.inventory_levels i
    set on_hand = i.on_hand - held.quantity, reserved = i.reserved - held.quantity
    from (
      select oi.product_id, coalesce(oi.size_code, '') as size_code, sum(oi.quantity)::integer as quantity
      from public.order_items oi
      where oi.order_id = v_order.id and oi.product_id is not null
      group by oi.product_id, coalesce(oi.size_code, '')
    ) held
    where i.product_id = held.product_id and i.size_code = held.size_code;

    update public.orders o set status = 'paid', paid_at = now() where o.id = v_order.id;
  else
    -- Paid after the reservation expired (or the order was cancelled): needs a refund or manual re-instatement.
    update public.orders o set needs_review = true where o.id = v_order.id;
  end if;

  return query
  select o.order_number, o.status, p.status
  from public.orders o join public.payments p on p.order_id = o.id
  where p.id = v_payment.id;
end;
$$;

revoke all on function public.confirm_payment(text, text, text, numeric, jsonb) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Release expired reservations every minute
-- ---------------------------------------------------------------------------

create extension if not exists pg_cron with schema pg_catalog;

select cron.schedule('expire-unpaid-orders', '* * * * *', 'select public.expire_unpaid_orders()');

-- ---------------------------------------------------------------------------
-- Accounts: consent and saved bags
-- ---------------------------------------------------------------------------

create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  confirmed_adult_at timestamptz,
  accepted_terms_at timestamptz,
  created_at timestamptz not null default now()
);

comment on table public.profiles is 'One row per shopper account. Consent timestamps satisfy PRD FR-003.';

alter table public.profiles enable row level security;
create policy "Shoppers can read their own profile" on public.profiles
  for select to authenticated using (id = (select auth.uid()));
grant select on public.profiles to authenticated;

-- Records that the signed-in shopper confirmed they are 18+ and accepted the terms and privacy notice.
create function public.record_signup_consent()
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'Sign in first.' using errcode = '42501';
  end if;
  insert into public.profiles (id, confirmed_adult_at, accepted_terms_at)
  values (auth.uid(), now(), now())
  on conflict (id) do update
  set confirmed_adult_at = coalesce(public.profiles.confirmed_adult_at, excluded.confirmed_adult_at),
      accepted_terms_at = coalesce(public.profiles.accepted_terms_at, excluded.accepted_terms_at);
end;
$$;

revoke all on function public.record_signup_consent() from public, anon;
grant execute on function public.record_signup_consent() to authenticated;

create table public.bag_items (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  product_id uuid not null references public.products (id) on delete cascade,
  size_code text not null default '',
  quantity integer not null check (quantity between 1 and 20),
  updated_at timestamptz not null default now(),
  primary key (user_id, product_id, size_code)
);

create index bag_items_product_id_idx on public.bag_items (product_id);

alter table public.bag_items enable row level security;
create policy "Shoppers manage their own bag" on public.bag_items
  for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));
revoke all on public.bag_items from anon;
grant select, insert, update, delete on public.bag_items to authenticated;

-- The signed-in shopper's bag with current names and prices.
create function public.get_bag()
returns table (
  slug text,
  name text,
  size_code text,
  size_label text,
  unit_price_ghs numeric,
  image_key text,
  tint text,
  kind public.product_kind,
  quantity integer,
  in_stock boolean
)
language sql
stable
security invoker
set search_path = ''
as $$
  select p.slug, p.name, nullif(b.size_code, ''), s.label, coalesce(s.price_ghs, p.price_ghs),
         p.image_key, p.tint, p.kind, b.quantity, coalesce(i.in_stock, false)
  from public.bag_items b
  join public.products p on p.id = b.product_id and p.is_published
  left join public.product_sizes s on s.product_id = b.product_id and s.code = b.size_code
  left join public.inventory_levels i on i.product_id = b.product_id and i.size_code = b.size_code
  where b.user_id = (select auth.uid())
  order by b.updated_at, p.name;
$$;

revoke all on function public.get_bag() from public, anon;
grant execute on function public.get_bag() to authenticated;

-- Replaces the signed-in shopper's bag. p_items: [{"slug", "size"?, "quantity"}]; unknown items are skipped.
create function public.set_bag(p_items jsonb)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'Sign in first.' using errcode = '42501';
  end if;
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) > 50 then
    raise exception 'Invalid bag.' using errcode = '22023';
  end if;

  delete from public.bag_items b where b.user_id = auth.uid();

  insert into public.bag_items (user_id, product_id, size_code, quantity, updated_at)
  select auth.uid(), p.id, coalesce(item ->> 'size', ''), least(sum((item ->> 'quantity')::integer), 20),
         now() + make_interval(secs => (min(ord) / 1000.0)::double precision)
  from jsonb_array_elements(p_items) with ordinality as e(item, ord)
  join public.products p on p.slug = item ->> 'slug' and p.is_published
  where jsonb_typeof(item -> 'quantity') = 'number'
    and (item ->> 'quantity')::numeric = trunc((item ->> 'quantity')::numeric)
    and (item ->> 'quantity')::integer between 1 and 20
    and (
      (item ->> 'size' is null and not exists (select 1 from public.product_sizes s where s.product_id = p.id))
      or exists (select 1 from public.product_sizes s where s.product_id = p.id and s.code = item ->> 'size')
    )
  group by p.id, coalesce(item ->> 'size', '');
end;
$$;

revoke all on function public.set_bag(jsonb) from public, anon;
grant execute on function public.set_bag(jsonb) to authenticated;

-- ===========================================================================
-- 20261016110143_order_statuses.sql
-- ===========================================================================

-- Order statuses from PRD FR-042, mapped onto the existing ones:
--   pending_payment = Pending payment, paid = Confirmed, packing = Packing, packed = Ready for dispatch,
--   out_for_delivery, delivered, delivery_failed = Delivery failed, cancelled, returned = Returned to the warehouse.
-- Kept in their own migration because Postgres can't use a new enum value in the transaction that adds it.

alter type public.order_status add value if not exists 'packing' after 'paid';
alter type public.order_status add value if not exists 'delivery_failed' after 'out_for_delivery';
alter type public.order_status add value if not exists 'returned' after 'cancelled';

-- ===========================================================================
-- 20261016110146_staff_and_audit.sql
-- ===========================================================================

-- Staff roles with required two-step verification (PRD FR-107) and an append-only audit log (FR-108).

-- ---------------------------------------------------------------------------
-- Staff
-- ---------------------------------------------------------------------------

create type public.staff_role as enum ('admin', 'catalogue', 'operations', 'support', 'finance', 'read_only');

-- Staff are matched to sign-in accounts by confirmed email address. Add the first admin with SQL:
--   insert into public.staff_members (email, role) values ('owner@example.com', 'admin');
create table public.staff_members (
  email text primary key check (email = lower(btrim(email)) and email like '%_@_%'),
  role public.staff_role not null,
  is_active boolean not null default true,
  added_by uuid references auth.users (id) on delete set null,
  added_at timestamptz not null default now()
);

alter table public.staff_members enable row level security;

-- The signed-in user's staff role, or NULL unless they are active staff AND completed two-step verification
-- in this session (assurance level aal2). Every staff permission check goes through this.
create function public.current_staff_role()
returns public.staff_role
language sql
stable
security definer
set search_path = ''
as $$
  select s.role
  from public.staff_members s
  join auth.users u on lower(u.email) = s.email
  where u.id = auth.uid()
    and u.email_confirmed_at is not null
    and s.is_active
    and coalesce(auth.jwt() ->> 'aal', '') = 'aal2';
$$;

revoke all on function public.current_staff_role() from public, anon;
grant execute on function public.current_staff_role() to authenticated;

-- What the admin console needs to route a signed-in user: their role (if any) and whether this session has
-- passed two-step verification. Says nothing about other people.
create function public.my_staff_access()
returns table (role public.staff_role, mfa_verified boolean)
language sql
stable
security definer
set search_path = ''
as $$
  select s.role, coalesce(auth.jwt() ->> 'aal', '') = 'aal2'
  from public.staff_members s
  join auth.users u on lower(u.email) = s.email
  where u.id = auth.uid() and u.email_confirmed_at is not null and s.is_active;
$$;

revoke all on function public.my_staff_access() from public, anon;
grant execute on function public.my_staff_access() to authenticated;

-- Raises unless the caller is verified staff with one of the given roles. Admins may do everything.
create function public.require_staff(p_roles public.staff_role[] default null)
returns public.staff_role
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_role public.staff_role := public.current_staff_role();
begin
  if v_role is null then
    raise exception 'Staff access with two-step verification is required.' using errcode = '42501';
  end if;
  if p_roles is not null and v_role <> 'admin' and not (v_role = any (p_roles)) then
    raise exception 'Your role (%) can''t do this.', replace(v_role::text, '_', ' ') using errcode = '42501';
  end if;
  return v_role;
end;
$$;

revoke all on function public.require_staff(public.staff_role[]) from public, anon, authenticated;

create policy "Staff can see the staff list" on public.staff_members
  for select to authenticated using ((select public.current_staff_role()) is not null);

grant select on public.staff_members to authenticated;

-- ---------------------------------------------------------------------------
-- Audit log
-- ---------------------------------------------------------------------------

create table public.audit_log (
  id bigint generated always as identity primary key,
  at timestamptz not null default now(),
  actor_id uuid,
  actor_email text,
  action text not null,
  entity text not null,
  entity_id text,
  details jsonb
);

create index audit_log_entity_idx on public.audit_log (entity, entity_id);

comment on table public.audit_log is 'Append-only record of sensitive staff actions (PRD FR-108). Entries cannot be changed.';

create function public.audit_log_is_append_only()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'Audit log entries cannot be changed or deleted.' using errcode = '42501';
end;
$$;

create trigger audit_log_append_only
  before update or delete on public.audit_log
  for each row execute function public.audit_log_is_append_only();

alter table public.audit_log enable row level security;

create policy "Admins can read the audit log" on public.audit_log
  for select to authenticated using ((select public.current_staff_role()) = 'admin');

grant select on public.audit_log to authenticated;

create function public.audit(p_action text, p_entity text, p_entity_id text, p_details jsonb default null)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.audit_log (actor_id, actor_email, action, entity, entity_id, details)
  values (auth.uid(), auth.jwt() ->> 'email', p_action, p_entity, p_entity_id, p_details);
$$;

revoke all on function public.audit(text, text, text, jsonb) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Managing staff (admins only)
-- ---------------------------------------------------------------------------

create function public.admin_set_staff(p_email text, p_role public.staff_role, p_active boolean default true)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_email text := lower(btrim(p_email));
  v_before public.staff_members%rowtype;
begin
  perform public.require_staff(array['admin']::public.staff_role[]);
  if v_email is null or v_email not like '%_@_%' then
    raise exception 'Enter a valid email address.' using errcode = '22023';
  end if;

  select * into v_before from public.staff_members s where s.email = v_email for update;

  insert into public.staff_members (email, role, is_active, added_by)
  values (v_email, p_role, p_active, auth.uid())
  on conflict (email) do update set role = excluded.role, is_active = excluded.is_active;

  if not exists (select 1 from public.staff_members s where s.role = 'admin' and s.is_active) then
    raise exception 'There must always be at least one active admin.' using errcode = '22023';
  end if;

  perform public.audit(
    case when v_before.email is null then 'staff.added' else 'staff.changed' end, 'staff', v_email,
    jsonb_build_object(
      'before', case when v_before.email is null then null
                     else jsonb_build_object('role', v_before.role, 'active', v_before.is_active) end,
      'after', jsonb_build_object('role', p_role, 'active', p_active)
    )
  );
end;
$$;

revoke all on function public.admin_set_staff(text, public.staff_role, boolean) from public, anon;
grant execute on function public.admin_set_staff(text, public.staff_role, boolean) to authenticated;

-- ===========================================================================
-- 20261016110148_order_tracking_notifications.sql
-- ===========================================================================

-- Order tracking: status history (FR-042), delivery details (FR-043 to FR-045), the customer's order page and
-- receipt (FR-028, FR-050) and transactional notifications (FR-060).

-- ---------------------------------------------------------------------------
-- Riders and delivery details on orders
-- ---------------------------------------------------------------------------

create table public.riders (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(btrim(name)) > 0),
  phone text not null check (length(btrim(phone)) > 0),
  vehicle text not null default 'Motorbike',
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

alter table public.riders enable row level security;

alter table public.orders
  -- Shown to the customer; the rider must get it from them to complete the delivery (proof of delivery, FR-044).
  add column delivery_code text not null default lpad(floor(random() * 10000)::integer::text, 4, '0'),
  add column rider_id uuid references public.riders (id) on delete set null,
  -- A courier partner's tracking reference, when a courier delivers instead of an in-house rider.
  add column courier_reference text,
  add column delivery_attempts integer not null default 0,
  add column delivered_at timestamptz,
  add column delivered_to text,
  -- Money was taken but the order won't be fulfilled: staff must refund it.
  add column refund_due boolean not null default false;

create index orders_rider_id_idx on public.orders (rider_id);
create index orders_status_created_idx on public.orders (status, created_at desc);

-- ---------------------------------------------------------------------------
-- Status history
-- ---------------------------------------------------------------------------

create table public.order_events (
  id bigint generated always as identity primary key,
  order_id uuid not null references public.orders (id) on delete cascade,
  status public.order_status not null,
  at timestamptz not null default now(),
  -- The staff member who made the change; NULL for the shopper, payments and scheduled jobs.
  actor_id uuid references auth.users (id) on delete set null,
  actor_email text,
  -- Staff-facing note and structured details such as a failed-delivery reason.
  note text,
  details jsonb
);

create index order_events_order_id_idx on public.order_events (order_id, at);

alter table public.order_events enable row level security;

-- Functions that change an order's status can attach a note and details to the history entry.
create function public.set_order_event_context(p_note text, p_details jsonb default null)
returns void
language sql
set search_path = ''
as $$
  select set_config('sleek.event_note', coalesce(p_note, ''), true),
         set_config('sleek.event_details', coalesce(p_details::text, ''), true);
$$;

revoke all on function public.set_order_event_context(text, jsonb) from public, anon, authenticated;

create function public.record_order_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' or new.status is distinct from old.status then
    insert into public.order_events (order_id, status, actor_id, actor_email, note, details)
    values (
      new.id, new.status,
      case when (select public.current_staff_role()) is not null then auth.uid() end,
      case when (select public.current_staff_role()) is not null then auth.jwt() ->> 'email' end,
      nullif(current_setting('sleek.event_note', true), ''),
      nullif(current_setting('sleek.event_details', true), '')::jsonb
    );
    perform public.set_order_event_context(null, null);
  end if;
  return null;
end;
$$;

create trigger orders_record_event
  after insert or update of status on public.orders
  for each row execute function public.record_order_event();

-- History for orders placed before this migration.
insert into public.order_events (order_id, status, at)
select o.id, 'pending_payment', o.created_at from public.orders o;
insert into public.order_events (order_id, status, at)
select o.id, o.status, coalesce(o.paid_at, o.updated_at) from public.orders o where o.status <> 'pending_payment';

-- ---------------------------------------------------------------------------
-- Notifications outbox
-- ---------------------------------------------------------------------------

create type public.notification_channel as enum ('sms', 'email');
create type public.notification_status as enum ('queued', 'sending', 'sent', 'failed', 'not_sent');

create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  order_id uuid references public.orders (id) on delete cascade,
  template text not null,
  channel public.notification_channel not null,
  recipient text not null,
  -- Snapshot of the values the message needs, taken when it was queued.
  payload jsonb not null default '{}',
  status public.notification_status not null default 'queued',
  attempts integer not null default 0,
  next_attempt_at timestamptz not null default now(),
  provider text,
  provider_reference text,
  last_error text,
  created_at timestamptz not null default now(),
  sent_at timestamptz
);

create index notifications_due_idx on public.notifications (next_attempt_at) where status in ('queued', 'sending');
create index notifications_order_id_idx on public.notifications (order_id);

alter table public.notifications enable row level security;

-- Queues the customer messages for a status change (PRD FR-060).
create function public.queue_order_notifications()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders%rowtype;
  v_template text;
  v_email text;
  v_payload jsonb;
begin
  select * into v_order from public.orders o where o.id = new.order_id;

  v_template := case new.status
    when 'paid' then 'order_confirmed'
    when 'packed' then 'order_packed'
    when 'out_for_delivery' then 'out_for_delivery'
    when 'delivered' then 'order_delivered'
    when 'delivery_failed' then 'delivery_failed'
    when 'returned' then 'order_returned'
    -- Unpaid orders that lapse are not worth a message; cancelled paid orders are.
    when 'cancelled' then case when v_order.paid_at is not null then 'order_cancelled' end
  end;
  if v_template is null then
    return null;
  end if;

  v_payload := jsonb_build_object(
    'order_number', v_order.order_number,
    'customer_name', v_order.customer_name,
    'total_ghs', v_order.total_ghs,
    'order_token', v_order.public_token,
    'delivery_code', v_order.delivery_code,
    'rider_name', (select r.name from public.riders r where r.id = v_order.rider_id),
    'courier_reference', v_order.courier_reference,
    'reason', new.details ->> 'reason',
    'refund_due', v_order.refund_due
  );

  insert into public.notifications (order_id, template, channel, recipient, payload)
  values (v_order.id, v_template, 'sms', v_order.phone, v_payload);

  select u.email into v_email from auth.users u where u.id = v_order.user_id;
  if v_email is not null then
    insert into public.notifications (order_id, template, channel, recipient, payload)
    values (v_order.id, v_template, 'email', v_email, v_payload);
  end if;
  return null;
end;
$$;

create trigger order_events_queue_notifications
  after insert on public.order_events
  for each row execute function public.queue_order_notifications();

-- Hands due messages to the sender. Messages stuck in "sending" (a crashed sender) are picked up again later.
create function public.claim_notifications(p_limit integer default 20)
returns table (
  id uuid,
  template text,
  channel public.notification_channel,
  recipient text,
  payload jsonb,
  attempts integer
)
language sql
security definer
set search_path = ''
as $$
  with due as (
    select n.id from public.notifications n
    where n.status in ('queued', 'sending') and n.next_attempt_at <= now()
    order by n.created_at
    limit greatest(1, least(p_limit, 100))
    for update skip locked
  )
  update public.notifications n
  set status = 'sending', attempts = n.attempts + 1, next_attempt_at = now() + interval '10 minutes'
  from due
  where n.id = due.id
  returning n.id, n.template, n.channel, n.recipient, n.payload, n.attempts;
$$;

revoke all on function public.claim_notifications(integer) from public, anon, authenticated;

-- Records the result of a send. Failures are retried with growing gaps, five attempts in all.
create function public.finish_notification(
  p_id uuid,
  p_outcome text,
  p_provider text default null,
  p_reference text default null,
  p_error text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_outcome not in ('sent', 'failed', 'not_sent') then
    raise exception 'Unknown outcome %.', p_outcome using errcode = '22023';
  end if;
  update public.notifications n
  set status = case
        when p_outcome = 'failed' and n.attempts < 5 then 'queued'
        else p_outcome::public.notification_status
      end,
      next_attempt_at = case when p_outcome = 'failed' then now() + make_interval(mins => power(2, n.attempts)::integer) else n.next_attempt_at end,
      provider = p_provider,
      provider_reference = p_reference,
      last_error = p_error,
      sent_at = case when p_outcome = 'sent' then now() end
  where n.id = p_id and n.status = 'sending';
end;
$$;

revoke all on function public.finish_notification(uuid, text, text, text, text) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Staff can read orders, payments and their history; all changes go through the admin_* functions.
-- ---------------------------------------------------------------------------

create policy "Staff can read all orders" on public.orders
  for select to authenticated using ((select public.current_staff_role()) is not null);

create policy "Staff can read all order items" on public.order_items
  for select to authenticated using ((select public.current_staff_role()) is not null);

create policy "Staff can read payments" on public.payments
  for select to authenticated using ((select public.current_staff_role()) is not null);

create policy "Staff can read order history" on public.order_events
  for select to authenticated using ((select public.current_staff_role()) is not null);

create policy "Staff can read notifications" on public.notifications
  for select to authenticated using ((select public.current_staff_role()) is not null);

create policy "Staff can read riders" on public.riders
  for select to authenticated using ((select public.current_staff_role()) is not null);

grant select on public.payments, public.order_events, public.notifications, public.riders to authenticated;

-- ---------------------------------------------------------------------------
-- Keep the delivery code secret from staff (FR-044)
-- ---------------------------------------------------------------------------
-- The delivery code proves the customer received the order, so nobody but the customer may read it: not through
-- the orders table, not through the order-page token (get_order shows it), and not through message payloads.
-- Column grants list every other column; give new orders columns a grant when you add them.

revoke select on public.orders from authenticated;
grant select (
  id, order_number, status, user_id, customer_name, phone, area, ghanapost_gps, rider_directions, delivery_option_id,
  is_gift, payment_method, momo_network, wallet_number, subtotal_ghs, delivery_fee_ghs, total_ghs, created_at,
  updated_at, reservation_expires_at, paid_at, cancel_reason, needs_review, rider_id, courier_reference,
  delivery_attempts, delivered_at, delivered_to, refund_due
) on public.orders to authenticated;

revoke select on public.notifications from authenticated;
grant select (
  id, order_id, template, channel, recipient, status, attempts, next_attempt_at, provider, provider_reference,
  last_error, created_at, sent_at
) on public.notifications to authenticated;

-- A signed-in shopper's own orders, newest first, with the links to their order pages.
create function public.my_orders()
returns table (
  order_number text,
  status public.order_status,
  created_at timestamptz,
  total_ghs numeric,
  item_count integer,
  order_token uuid
)
language sql
stable
security definer
set search_path = ''
as $$
  select o.order_number, o.status, o.created_at, o.total_ghs,
         (select coalesce(sum(i.quantity), 0)::integer from public.order_items i where i.order_id = o.id),
         o.public_token
  from public.orders o
  where o.user_id = auth.uid()
  order by o.created_at desc;
$$;

revoke all on function public.my_orders() from public, anon;
grant execute on function public.my_orders() to authenticated;

-- ===========================================================================
-- 20261016110151_catalogue_inventory.sql
-- ===========================================================================

-- Catalogue management with publishing rules and recalls (PRD FR-100, FR-101), and inventory by batch with
-- expiry dates, a movement ledger and alerts (FR-102, FR-103).
--
-- Stock model:
--   stock_batches.quantity    physical units of a batch in the warehouse (goes down when an order is packed).
--   inventory_levels.on_hand  units that can still be sold: units in usable batches, minus units already sold but
--                             not yet packed. It can drop below `reserved` (even below zero) when stock is recalled,
--                             quarantined or expires while orders hold it; that shortfall is real and shows up when
--                             those orders are packed.

-- ---------------------------------------------------------------------------
-- Product compliance fields and stock thresholds
-- ---------------------------------------------------------------------------

alter table public.products
  -- INCI ingredient list (beauty, bath) or materials (toys, clothing).
  add column ingredients text,
  add column country_of_origin text,
  -- Regulatory reference, e.g. the Ghana FDA registration number. Required for cosmetics.
  add column regulatory_reference text,
  add column period_after_opening text,
  add column recalled_at timestamptz,
  add column recall_reason text;

alter table public.categories
  add column low_stock_threshold integer check (low_stock_threshold >= 0),
  add column expiry_alert_days integer check (expiry_alert_days > 0);

alter table public.store_settings
  add column low_stock_threshold integer not null default 5 check (low_stock_threshold >= 0),
  add column expiry_alert_days integer not null default 90 check (expiry_alert_days > 0),
  add column max_delivery_attempts integer not null default 2 check (max_delivery_attempts between 1 and 5),
  add column require_delivery_code boolean not null default true;

alter table public.inventory_levels
  drop constraint inventory_reserved_within_on_hand,
  drop constraint inventory_levels_on_hand_check;

-- ---------------------------------------------------------------------------
-- Batches, the movement ledger and batch allocations
-- ---------------------------------------------------------------------------

create type public.batch_status as enum ('available', 'quarantined', 'recalled', 'expired');

create table public.stock_batches (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null,
  size_code text not null default '',
  batch_code text not null check (length(btrim(batch_code)) > 0),
  expires_on date,
  quantity integer not null check (quantity >= 0),
  status public.batch_status not null default 'available',
  received_at timestamptz not null default now(),
  -- Supplier, invoice or delivery note reference.
  note text,
  foreign key (product_id, size_code) references public.inventory_levels (product_id, size_code) on delete cascade,
  unique (product_id, size_code, batch_code)
);

create index stock_batches_expiry_idx on public.stock_batches (expires_on) where status = 'available' and quantity > 0;

create type public.stock_movement_reason as enum (
  'opening', 'received', 'sold', 'picked', 'returned', 'restocked',
  'adjusted', 'damaged', 'lost', 'found',
  'quarantined', 'released', 'recalled', 'expired', 'written_off'
);

create table public.stock_movements (
  id bigint generated always as identity primary key,
  at timestamptz not null default now(),
  -- No cascade: a product with stock history can't be deleted, so the ledger stays complete.
  product_id uuid not null references public.products (id),
  size_code text not null default '',
  batch_id uuid references public.stock_batches (id) on delete set null,
  reason public.stock_movement_reason not null,
  -- Change in physical units of the batch.
  quantity integer not null default 0,
  -- Change in units that can be sold (inventory_levels.on_hand).
  sellable_change integer not null default 0,
  order_id uuid references public.orders (id) on delete set null,
  actor_id uuid,
  actor_email text,
  note text
);

create index stock_movements_sku_idx on public.stock_movements (product_id, size_code, at desc);
create index stock_movements_batch_idx on public.stock_movements (batch_id);
create index stock_movements_order_idx on public.stock_movements (order_id);

-- Which batches each order line was packed from, for recalls and returns.
create table public.order_item_batches (
  order_item_id uuid not null references public.order_items (id) on delete cascade,
  batch_id uuid not null references public.stock_batches (id),
  quantity integer not null check (quantity > 0),
  primary key (order_item_id, batch_id)
);

create index order_item_batches_batch_idx on public.order_item_batches (batch_id);

alter table public.stock_batches enable row level security;
alter table public.stock_movements enable row level security;
alter table public.order_item_batches enable row level security;

-- Stock already on hand becomes an opening batch with no expiry date recorded. Paid orders that are not packed yet
-- still need their units, so those go into the batch too. The ledger then adds up: per unit, the movements'
-- sellable_change sums to on_hand, and per batch their quantity sums to the batch's quantity.
with levels as (
  select i.product_id, i.size_code, i.on_hand,
         i.on_hand + coalesce((
           select sum(oi.quantity)::integer from public.order_items oi join public.orders o on o.id = oi.order_id
           where oi.product_id = i.product_id and coalesce(oi.size_code, '') = i.size_code and o.status = 'paid'
         ), 0) as physical
  from public.inventory_levels i
),
batches as (
  insert into public.stock_batches (product_id, size_code, batch_code, quantity, note)
  select l.product_id, l.size_code, 'OPENING', l.physical, 'Stock on hand when batches were introduced'
  from levels l where l.physical > 0
  returning id, product_id, size_code, quantity, note
)
insert into public.stock_movements (product_id, size_code, batch_id, reason, quantity, sellable_change, note)
select b.product_id, b.size_code, b.id, 'opening', b.quantity, l.on_hand, b.note
from batches b join levels l on l.product_id = b.product_id and l.size_code = b.size_code;

-- Records a movement with the signed-in staff member as the actor.
create function public.log_stock_movement(
  p_product_id uuid,
  p_size_code text,
  p_batch_id uuid,
  p_reason public.stock_movement_reason,
  p_quantity integer,
  p_sellable_change integer,
  p_order_id uuid default null,
  p_note text default null
)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.stock_movements
    (product_id, size_code, batch_id, reason, quantity, sellable_change, order_id, actor_id, actor_email, note)
  values (
    p_product_id, p_size_code, p_batch_id, p_reason, p_quantity, p_sellable_change, p_order_id,
    auth.uid(), auth.jwt() ->> 'email', nullif(btrim(p_note), '')
  );
$$;

revoke all on function public.log_stock_movement(uuid, text, uuid, public.stock_movement_reason, integer, integer, uuid, text)
  from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Payments: a sale now also lands in the stock ledger
-- ---------------------------------------------------------------------------
create or replace function public.confirm_payment(
  p_provider text,
  p_reference text,
  p_status text,
  p_amount_ghs numeric,
  p_event jsonb default null
)
returns table (order_number text, order_status public.order_status, payment_status public.payment_status)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payment public.payments%rowtype;
  v_order public.orders%rowtype;
begin
  if p_status not in ('succeeded', 'failed') then
    raise exception 'Unknown payment status %.', p_status using errcode = '22023';
  end if;

  select * into v_payment from public.payments p
  where p.provider = p_provider and p.provider_reference = p_reference
  for update;
  if not found then
    raise exception 'Unknown payment %.', p_reference using errcode = '22023';
  end if;

  select * into v_order from public.orders o where o.id = v_payment.order_id for update;

  -- Final states are final: repeated or out-of-order notifications change nothing.
  if v_payment.status in ('succeeded', 'failed') then
    return query select v_order.order_number, v_order.status, v_payment.status;
    return;
  end if;

  update public.payments p
  set status = p_status::public.payment_status, last_event = p_event
  where p.id = v_payment.id;

  if p_status = 'failed' then
    perform public.release_order_reservation(v_order.id, 'payment_failed');
  elsif p_amount_ghs is distinct from v_payment.amount_ghs then
    -- Money arrived but not the amount we asked for: leave the order for staff to resolve.
    update public.orders o set needs_review = true where o.id = v_order.id;
  elsif v_order.status = 'pending_payment' then
    -- Turn the reservation into a sale, and log it in the stock ledger.
    with held as (
      select oi.product_id, coalesce(oi.size_code, '') as size_code, sum(oi.quantity)::integer as quantity
      from public.order_items oi
      where oi.order_id = v_order.id and oi.product_id is not null
      group by oi.product_id, coalesce(oi.size_code, '')
    ),
    sold as (
      update public.inventory_levels i
      set on_hand = i.on_hand - held.quantity, reserved = i.reserved - held.quantity
      from held
      where i.product_id = held.product_id and i.size_code = held.size_code
      returning i.product_id, i.size_code, held.quantity
    )
    insert into public.stock_movements (product_id, size_code, reason, quantity, sellable_change, order_id)
    select sold.product_id, sold.size_code, 'sold', 0, -sold.quantity, v_order.id from sold;

    update public.orders o set status = 'paid', paid_at = now() where o.id = v_order.id;
  else
    -- Paid after the reservation expired (or the order was cancelled): needs a refund or manual re-instatement.
    update public.orders o set needs_review = true where o.id = v_order.id;
  end if;

  return query
  select o.order_number, o.status, p.status
  from public.orders o join public.payments p on p.order_id = o.id
  where p.id = v_payment.id;
end;
$$;


-- ---------------------------------------------------------------------------
-- Publishing rules (FR-100)
-- ---------------------------------------------------------------------------

-- What a product still needs before it can be shown on the store. Empty when it can be published.
create function public.product_publish_problems(p_product_id uuid)
returns text[]
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  p public.products%rowtype;
  v_cosmetic boolean;
  v_missing text[] := '{}'::text[];
begin
  select * into p from public.products where id = p_product_id;
  if not found then
    return array['product not found'];
  end if;
  v_cosmetic := p.department = 'beauty' or p.kids_filter = 'bath';

  if coalesce(btrim(p.brand), '') = '' then v_missing := v_missing || 'brand'::text; end if;
  if p.category_id is null then v_missing := v_missing || 'category'::text; end if;
  if coalesce(btrim(p.details ->> 'description'), '') = '' then v_missing := v_missing || 'description'::text; end if;
  if coalesce(btrim(p.ingredients), '') = '' then
    v_missing := v_missing || (case when v_cosmetic then 'ingredients' else 'materials' end)::text;
  end if;
  if coalesce(btrim(p.details ->> 'warnings'), '') = '' then v_missing := v_missing || 'safety notes'::text; end if;
  if coalesce(btrim(p.country_of_origin), '') = '' then v_missing := v_missing || 'country of origin'::text; end if;
  if v_cosmetic and coalesce(btrim(p.regulatory_reference), '') = '' then
    v_missing := v_missing || 'FDA registration number'::text;
  end if;
  if p.department = 'kids' and (
    coalesce(btrim(p.details ->> 'recommendedAge'), '') = ''
    or not exists (select 1 from public.product_age_bands b where b.product_id = p.id)
  ) then
    v_missing := v_missing || 'age range'::text;
  end if;
  if p.recalled_at is not null then v_missing := v_missing || 'recall lifted'::text; end if;
  return v_missing;
end;
$$;

revoke all on function public.product_publish_problems(uuid) from public, anon;
grant execute on function public.product_publish_problems(uuid) to authenticated;

-- Creates or updates a product with its sizes and age bands. Returns {id, slug, published, problems}:
-- a product that asks to be published but is missing required fields is saved as a draft instead.
--
-- p: {id?, slug?, name, brand, department, category_id, kids_filter, kind, price_ghs, was_price_ghs, badge, tag,
--     summary, image_key, tint, description, highlights[], free_from[], recommended_age, warnings, how_to_use,
--     ingredients, country_of_origin, regulatory_reference, period_after_opening,
--     sizes: [{code, label, price_ghs, is_default}], age_bands: [id], publish}
create function public.admin_save_product(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  v_before public.products%rowtype;
  v_name text := btrim(coalesce(p ->> 'name', ''));
  v_slug text;
  v_department public.department;
  v_kind public.product_kind;
  v_kids_filter public.kids_filter;
  v_price numeric;
  v_was numeric;
  v_sizes jsonb := coalesce(p -> 'sizes', '[]'::jsonb);
  v_bands jsonb := coalesce(p -> 'age_bands', '[]'::jsonb);
  v_codes text[];
  v_default_price numeric;
  v_default_ord bigint := 0;
  v_code text;
  v_details jsonb;
  v_problems text[];
  v_publish boolean := coalesce((p ->> 'publish')::boolean, false);
  v_published boolean;
begin
  perform public.require_staff(array['catalogue']::public.staff_role[]);

  if v_name = '' or length(v_name) > 120 then
    raise exception 'Enter a product name (up to 120 characters).' using errcode = '22023';
  end if;

  v_slug := lower(btrim(coalesce(nullif(p ->> 'slug', ''), v_name)));
  v_slug := btrim(regexp_replace(regexp_replace(v_slug, '[^a-z0-9]+', '-', 'g'), '-+', '-', 'g'), '-');
  if v_slug = '' then
    raise exception 'Enter a web address for the product.' using errcode = '22023';
  end if;
  if exists (select 1 from public.products x where x.slug = v_slug and x.id is distinct from v_id) then
    raise exception 'Another product already uses the web address "%".', v_slug using errcode = '22023';
  end if;

  begin
    v_department := (p ->> 'department')::public.department;
    v_kind := (p ->> 'kind')::public.product_kind;
    v_kids_filter := nullif(p ->> 'kids_filter', '')::public.kids_filter;
  exception when invalid_text_representation then
    raise exception 'Choose a department, product type and kids filter from the lists.' using errcode = '22023';
  end;
  if v_department is null or v_kind is null then
    raise exception 'Choose a department and product type.' using errcode = '22023';
  end if;
  if v_department = 'beauty' then
    v_kids_filter := null;
  end if;

  if nullif(p ->> 'category_id', '') is not null
     and not exists (select 1 from public.categories c where c.id = p ->> 'category_id') then
    raise exception 'Choose a category from the list.' using errcode = '22023';
  end if;

  begin
    v_price := nullif(btrim(p ->> 'price_ghs'), '')::numeric;
    v_was := nullif(btrim(p ->> 'was_price_ghs'), '')::numeric;
  exception when invalid_text_representation then
    raise exception 'Prices must be numbers.' using errcode = '22023';
  end;

  -- Sizes: unique codes, at most one default; the product price is the default size's price.
  if jsonb_typeof(v_sizes) <> 'array' or jsonb_typeof(v_bands) <> 'array' then
    raise exception 'Invalid sizes or age bands.' using errcode = '22023';
  end if;
  select array_agg(lower(btrim(s ->> 'code'))) into v_codes from jsonb_array_elements(v_sizes) s;
  if v_codes is not null then
    if exists (select 1 from unnest(v_codes) c where c = '' or c !~ '^[a-z0-9][a-z0-9-]*$') then
      raise exception 'Size codes may use lowercase letters, numbers and dashes only.' using errcode = '22023';
    end if;
    if (select count(distinct c) from unnest(v_codes) c) <> cardinality(v_codes) then
      raise exception 'Each size needs its own code.' using errcode = '22023';
    end if;
    if exists (select 1 from jsonb_array_elements(v_sizes) s where coalesce(btrim(s ->> 'label'), '') = '') then
      raise exception 'Give every size a label, e.g. "200 ml".' using errcode = '22023';
    end if;
    begin
      if exists (select 1 from jsonb_array_elements(v_sizes) s where (s ->> 'price_ghs')::numeric < 0) then
        raise exception 'Prices can''t be negative.' using errcode = '22023';
      end if;
      select (s ->> 'price_ghs')::numeric, ord into v_default_price, v_default_ord
      from jsonb_array_elements(v_sizes) with ordinality as e(s, ord)
      order by coalesce((s ->> 'is_default')::boolean, false) desc, ord
      limit 1;
    exception when invalid_text_representation then
      raise exception 'Size prices must be numbers.' using errcode = '22023';
    end;
    v_price := v_default_price;
  end if;

  if v_price is null or v_price < 0 then
    raise exception 'Enter a price.' using errcode = '22023';
  end if;
  if v_was is not null and v_was <= v_price then
    raise exception 'The "was" price must be higher than the price.' using errcode = '22023';
  end if;

  v_details := jsonb_strip_nulls(jsonb_build_object(
    'description', nullif(btrim(p ->> 'description'), ''),
    'highlights', case when jsonb_typeof(p -> 'highlights') = 'array' and jsonb_array_length(p -> 'highlights') > 0
                       then p -> 'highlights' end,
    'freeFrom', case when jsonb_typeof(p -> 'free_from') = 'array' and jsonb_array_length(p -> 'free_from') > 0
                     then p -> 'free_from' end,
    'recommendedAge', nullif(btrim(p ->> 'recommended_age'), ''),
    'warnings', nullif(btrim(p ->> 'warnings'), ''),
    'howToUse', nullif(btrim(p ->> 'how_to_use'), '')
  ));

  if v_id is null then
    insert into public.products (
      slug, name, brand, department, category_id, kids_filter, collection, price_ghs, was_price_ghs, badge, tag,
      summary, image_key, tint, kind, details, ingredients, country_of_origin, regulatory_reference,
      period_after_opening, is_published
    ) values (
      v_slug, v_name, nullif(btrim(p ->> 'brand'), ''), v_department, nullif(p ->> 'category_id', ''), v_kids_filter,
      null, v_price, v_was, nullif(btrim(p ->> 'badge'), ''), coalesce(btrim(p ->> 'tag'), ''),
      coalesce(btrim(p ->> 'summary'), ''), nullif(p ->> 'image_key', ''),
      coalesce(nullif(p ->> 'tint', ''), case when v_department = 'beauty' then '#F4E3D7' else '#E3F0EC' end),
      v_kind, v_details, nullif(btrim(p ->> 'ingredients'), ''), nullif(btrim(p ->> 'country_of_origin'), ''),
      nullif(btrim(p ->> 'regulatory_reference'), ''), nullif(btrim(p ->> 'period_after_opening'), ''), false
    )
    returning id into v_id;
    perform public.audit('product.created', 'product', v_id::text, jsonb_build_object('slug', v_slug, 'price_ghs', v_price));
  else
    select * into v_before from public.products x where x.id = v_id for update;
    if not found then
      raise exception 'That product no longer exists.' using errcode = '22023';
    end if;
    update public.products x set
      slug = v_slug, name = v_name, brand = nullif(btrim(p ->> 'brand'), ''), department = v_department,
      category_id = nullif(p ->> 'category_id', ''), kids_filter = v_kids_filter, price_ghs = v_price,
      was_price_ghs = v_was, badge = nullif(btrim(p ->> 'badge'), ''), tag = coalesce(btrim(p ->> 'tag'), ''),
      summary = coalesce(btrim(p ->> 'summary'), ''), image_key = nullif(p ->> 'image_key', ''),
      tint = coalesce(nullif(p ->> 'tint', ''), x.tint), kind = v_kind,
      -- Keep content the form doesn't edit, such as the photo gallery.
      details = (coalesce(x.details, '{}'::jsonb) - array['description', 'highlights', 'freeFrom', 'recommendedAge',
                 'warnings', 'howToUse']) || v_details,
      ingredients = nullif(btrim(p ->> 'ingredients'), ''),
      country_of_origin = nullif(btrim(p ->> 'country_of_origin'), ''),
      regulatory_reference = nullif(btrim(p ->> 'regulatory_reference'), ''),
      period_after_opening = nullif(btrim(p ->> 'period_after_opening'), '')
    where x.id = v_id;
    if v_before.price_ghs is distinct from v_price or v_before.was_price_ghs is distinct from v_was then
      perform public.audit('product.price_changed', 'product', v_id::text, jsonb_build_object(
        'before', jsonb_build_object('price_ghs', v_before.price_ghs, 'was_price_ghs', v_before.was_price_ghs),
        'after', jsonb_build_object('price_ghs', v_price, 'was_price_ghs', v_was)));
    end if;
  end if;

  -- Sizes and the stock rows that go with them.
  delete from public.product_sizes s where s.product_id = v_id;
  insert into public.product_sizes (product_id, code, label, price_ghs, is_default, sort_order)
  select v_id, lower(btrim(s ->> 'code')), btrim(s ->> 'label'), (s ->> 'price_ghs')::numeric,
         ord = v_default_ord, (ord - 1)::smallint
  from jsonb_array_elements(v_sizes) with ordinality as e(s, ord);

  v_codes := coalesce(v_codes, array['']);
  foreach v_code in array v_codes loop
    insert into public.inventory_levels (product_id, size_code) values (v_id, v_code) on conflict do nothing;
  end loop;
  for v_code in
    select i.size_code from public.inventory_levels i where i.product_id = v_id and i.size_code <> all (v_codes)
  loop
    if exists (select 1 from public.inventory_levels i where i.product_id = v_id and i.size_code = v_code
                 and (i.on_hand <> 0 or i.reserved <> 0))
       or exists (select 1 from public.stock_batches b where b.product_id = v_id and b.size_code = v_code
                    and b.quantity > 0) then
      raise exception 'Size "%" still has stock. Write it off or sell it before removing the size.',
        coalesce(nullif(v_code, ''), 'one size') using errcode = '22023';
    end if;
    delete from public.inventory_levels i where i.product_id = v_id and i.size_code = v_code;
  end loop;

  delete from public.product_age_bands b where b.product_id = v_id;
  insert into public.product_age_bands (product_id, age_band_id)
  select v_id, band from jsonb_array_elements_text(v_bands) band
  where exists (select 1 from public.age_bands a where a.id = band)
  on conflict do nothing;

  -- Publishing (FR-100): only complete products go on the store.
  v_problems := public.product_publish_problems(v_id);
  v_published := v_publish and cardinality(v_problems) = 0;
  update public.products x set is_published = v_published where x.id = v_id and x.is_published <> v_published;
  if found then
    perform public.audit(case when v_published then 'product.published' else 'product.unpublished' end,
      'product', v_id::text, null);
  end if;

  return jsonb_build_object('id', v_id, 'slug', v_slug, 'published', v_published, 'problems', to_jsonb(v_problems));
end;
$$;

revoke all on function public.admin_save_product(jsonb) from public, anon;
grant execute on function public.admin_save_product(jsonb) to authenticated;

-- Shows or hides a product on the store. Returns what is still missing when it can't be published.
create function public.admin_set_product_published(p_product_id uuid, p_published boolean)
returns text[]
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_problems text[] := '{}'::text[];
begin
  perform public.require_staff(array['catalogue']::public.staff_role[]);
  if p_published then
    v_problems := public.product_publish_problems(p_product_id);
    if cardinality(v_problems) > 0 then
      return v_problems;
    end if;
  end if;
  update public.products x set is_published = p_published where x.id = p_product_id and x.is_published <> p_published;
  if found then
    perform public.audit(case when p_published then 'product.published' else 'product.unpublished' end,
      'product', p_product_id::text, null);
  end if;
  return v_problems;
end;
$$;

revoke all on function public.admin_set_product_published(uuid, boolean) from public, anon;
grant execute on function public.admin_set_product_published(uuid, boolean) to authenticated;

-- ---------------------------------------------------------------------------
-- Batch status changes (shared by recalls, quarantine and expiry)
-- ---------------------------------------------------------------------------

create function public.change_batch_status(
  p_batch_id uuid,
  p_status public.batch_status,
  p_reason public.stock_movement_reason,
  p_note text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  b public.stock_batches%rowtype;
  v_sellable integer := 0;
begin
  select * into b from public.stock_batches x where x.id = p_batch_id for update;
  if not found then
    raise exception 'That batch no longer exists.' using errcode = '22023';
  end if;
  if b.status = p_status then
    return;
  end if;
  if b.status in ('recalled', 'expired') then
    raise exception 'Batch % is %; it can only be written off.', b.batch_code, b.status using errcode = '22023';
  end if;
  if p_status = 'available' and b.expires_on < current_date then
    raise exception 'Batch % is past its expiry date.', b.batch_code using errcode = '22023';
  end if;

  if b.status = 'available' then
    v_sellable := -b.quantity;
  elsif p_status = 'available' then
    v_sellable := b.quantity;
  end if;

  update public.stock_batches x set status = p_status where x.id = b.id;
  update public.inventory_levels i set on_hand = i.on_hand + v_sellable
  where i.product_id = b.product_id and i.size_code = b.size_code;
  perform public.log_stock_movement(b.product_id, b.size_code, b.id, p_reason, 0, v_sellable, null, p_note);

  -- Packed orders carrying a recalled batch must be stopped before they reach a customer.
  if p_status = 'recalled' then
    update public.orders o set needs_review = true
    where o.status in ('packing', 'packed', 'out_for_delivery', 'delivery_failed')
      and exists (select 1 from public.order_item_batches ab join public.order_items oi on oi.id = ab.order_item_id
                  where ab.batch_id = b.id and oi.order_id = o.id);
  end if;
end;
$$;

revoke all on function public.change_batch_status(uuid, public.batch_status, public.stock_movement_reason, text)
  from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Recalls (FR-101)
-- ---------------------------------------------------------------------------

create function public.admin_recall_product(p_product_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_batch uuid;
begin
  perform public.require_staff(array['catalogue', 'operations']::public.staff_role[]);
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'Give a reason for the recall.' using errcode = '22023';
  end if;
  update public.products x set is_published = false, recalled_at = now(), recall_reason = btrim(p_reason)
  where x.id = p_product_id;
  if not found then
    raise exception 'That product no longer exists.' using errcode = '22023';
  end if;

  for v_batch in
    select b.id from public.stock_batches b where b.product_id = p_product_id and b.status in ('available', 'quarantined')
  loop
    perform public.change_batch_status(v_batch, 'recalled', 'recalled', p_reason);
  end loop;

  -- Paid orders that haven't gone out yet need a decision from staff.
  update public.orders o set needs_review = true
  where o.status in ('paid', 'packing', 'packed', 'out_for_delivery', 'delivery_failed')
    and exists (select 1 from public.order_items oi where oi.order_id = o.id and oi.product_id = p_product_id);

  perform public.audit('product.recalled', 'product', p_product_id::text, jsonb_build_object('reason', btrim(p_reason)));
end;
$$;

revoke all on function public.admin_recall_product(uuid, text) from public, anon;
grant execute on function public.admin_recall_product(uuid, text) to authenticated;

-- Lifts a product recall so it can be published again. Its recalled batches stay recalled.
create function public.admin_lift_recall(p_product_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.require_staff(array['admin']::public.staff_role[]);
  update public.products x set recalled_at = null, recall_reason = null where x.id = p_product_id;
  perform public.audit('product.recall_lifted', 'product', p_product_id::text, null);
end;
$$;

revoke all on function public.admin_lift_recall(uuid) from public, anon;
grant execute on function public.admin_lift_recall(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- Stock changes (FR-102). Every one is logged with who, when and why.
-- ---------------------------------------------------------------------------

-- Receives stock into a batch. Cosmetics need an expiry date.
create function public.admin_receive_stock(
  p_product_id uuid,
  p_size_code text,
  p_batch_code text,
  p_expires_on date,
  p_quantity integer,
  p_note text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_product public.products%rowtype;
  v_code text := upper(btrim(coalesce(p_batch_code, '')));
  v_size text := coalesce(p_size_code, '');
  v_batch public.stock_batches%rowtype;
begin
  perform public.require_staff(array['operations']::public.staff_role[]);
  select * into v_product from public.products x where x.id = p_product_id;
  if not found or not exists (select 1 from public.inventory_levels i where i.product_id = p_product_id and i.size_code = v_size) then
    raise exception 'Choose a product and size.' using errcode = '22023';
  end if;
  if v_code = '' then
    raise exception 'Enter the batch number printed on the pack.' using errcode = '22023';
  end if;
  if p_quantity is null or p_quantity < 1 or p_quantity > 100000 then
    raise exception 'Enter how many units arrived.' using errcode = '22023';
  end if;
  if p_expires_on is null and (v_product.department = 'beauty' or v_product.kids_filter = 'bath') then
    raise exception 'Enter the expiry date; it''s required for beauty and bath products.' using errcode = '22023';
  end if;
  if p_expires_on <= current_date then
    raise exception 'That expiry date has already passed.' using errcode = '22023';
  end if;

  select * into v_batch from public.stock_batches b
  where b.product_id = p_product_id and b.size_code = v_size and b.batch_code = v_code for update;
  if found then
    if v_batch.status <> 'available' then
      raise exception 'Batch % is %, so new stock can''t be added to it.', v_code, v_batch.status using errcode = '22023';
    end if;
    if v_batch.expires_on is distinct from p_expires_on then
      raise exception 'Batch % is already recorded with expiry %.', v_code, coalesce(v_batch.expires_on::text, 'not set')
        using errcode = '22023';
    end if;
    update public.stock_batches b set quantity = b.quantity + p_quantity where b.id = v_batch.id;
  else
    insert into public.stock_batches (product_id, size_code, batch_code, expires_on, quantity, note)
    values (p_product_id, v_size, v_code, p_expires_on, p_quantity, nullif(btrim(p_note), ''))
    returning * into v_batch;
  end if;

  update public.inventory_levels i set on_hand = i.on_hand + p_quantity
  where i.product_id = p_product_id and i.size_code = v_size;
  perform public.log_stock_movement(p_product_id, v_size, v_batch.id, 'received', p_quantity, p_quantity, null, p_note);
  perform public.audit('stock.received', 'batch', v_batch.id::text,
    jsonb_build_object('batch_code', v_code, 'quantity', p_quantity, 'expires_on', p_expires_on));
  return v_batch.id;
end;
$$;

revoke all on function public.admin_receive_stock(uuid, text, text, date, integer, text) from public, anon;
grant execute on function public.admin_receive_stock(uuid, text, text, date, integer, text) to authenticated;

-- Corrects a batch count: damage, loss, a recount. A note is required.
create function public.admin_adjust_batch(
  p_batch_id uuid,
  p_change integer,
  p_reason public.stock_movement_reason,
  p_note text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  b public.stock_batches%rowtype;
  v_sellable integer;
begin
  perform public.require_staff(array['operations']::public.staff_role[]);
  if p_reason not in ('adjusted', 'damaged', 'lost', 'found') then
    raise exception 'Choose why the count changed.' using errcode = '22023';
  end if;
  if coalesce(btrim(p_note), '') = '' then
    raise exception 'Add a note explaining the change.' using errcode = '22023';
  end if;
  if p_change is null or p_change = 0 then
    raise exception 'Enter how many units to add or remove.' using errcode = '22023';
  end if;
  select * into b from public.stock_batches x where x.id = p_batch_id for update;
  if not found then
    raise exception 'That batch no longer exists.' using errcode = '22023';
  end if;
  if b.quantity + p_change < 0 then
    raise exception 'Batch % only has % units.', b.batch_code, b.quantity using errcode = '22023';
  end if;

  v_sellable := case when b.status = 'available' then p_change else 0 end;
  update public.stock_batches x set quantity = x.quantity + p_change where x.id = b.id;
  update public.inventory_levels i set on_hand = i.on_hand + v_sellable
  where i.product_id = b.product_id and i.size_code = b.size_code;
  perform public.log_stock_movement(b.product_id, b.size_code, b.id, p_reason, p_change, v_sellable, null, p_note);
  perform public.audit('stock.adjusted', 'batch', b.id::text,
    jsonb_build_object('batch_code', b.batch_code, 'change', p_change, 'reason', p_reason, 'note', btrim(p_note)));
end;
$$;

revoke all on function public.admin_adjust_batch(uuid, integer, public.stock_movement_reason, text) from public, anon;
grant execute on function public.admin_adjust_batch(uuid, integer, public.stock_movement_reason, text) to authenticated;

-- Quarantines, releases or recalls a batch.
create function public.admin_set_batch_status(p_batch_id uuid, p_status public.batch_status, p_note text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_status = 'recalled' then
    perform public.require_staff(array['catalogue', 'operations']::public.staff_role[]);
  elsif p_status in ('quarantined', 'available') then
    perform public.require_staff(array['operations']::public.staff_role[]);
  else
    raise exception 'Batches expire on their own; choose quarantine, release or recall.' using errcode = '22023';
  end if;
  if p_status <> 'available' and coalesce(btrim(p_note), '') = '' then
    raise exception 'Add a note explaining why.' using errcode = '22023';
  end if;
  perform public.change_batch_status(p_batch_id, p_status,
    (case p_status when 'available' then 'released' else p_status::text end)::public.stock_movement_reason, p_note);
  perform public.audit('batch.' || p_status::text, 'batch', p_batch_id::text, jsonb_build_object('note', btrim(p_note)));
end;
$$;

revoke all on function public.admin_set_batch_status(uuid, public.batch_status, text) from public, anon;
grant execute on function public.admin_set_batch_status(uuid, public.batch_status, text) to authenticated;

-- Disposes of a batch that is out of sale (quarantined, recalled or expired).
create function public.admin_write_off_batch(p_batch_id uuid, p_note text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  b public.stock_batches%rowtype;
begin
  perform public.require_staff(array['operations']::public.staff_role[]);
  select * into b from public.stock_batches x where x.id = p_batch_id for update;
  if not found then
    raise exception 'That batch no longer exists.' using errcode = '22023';
  end if;
  if b.status = 'available' then
    raise exception 'Quarantine batch % before writing it off.', b.batch_code using errcode = '22023';
  end if;
  if b.quantity = 0 then
    return;
  end if;
  update public.stock_batches x set quantity = 0 where x.id = b.id;
  perform public.log_stock_movement(b.product_id, b.size_code, b.id, 'written_off', -b.quantity, 0, null, p_note);
  perform public.audit('batch.written_off', 'batch', b.id::text,
    jsonb_build_object('batch_code', b.batch_code, 'quantity', b.quantity, 'note', btrim(p_note)));
end;
$$;

revoke all on function public.admin_write_off_batch(uuid, text) from public, anon;
grant execute on function public.admin_write_off_batch(uuid, text) to authenticated;

-- Takes batches past their expiry date off sale. Runs daily.
create function public.expire_batches()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_batch uuid;
  v_count integer := 0;
begin
  for v_batch in
    select b.id from public.stock_batches b
    where b.status = 'available' and b.expires_on < current_date
    for update skip locked
  loop
    perform public.change_batch_status(v_batch, 'expired', 'expired', 'Past its expiry date');
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;

revoke all on function public.expire_batches() from public, anon, authenticated;

select cron.schedule('expire-batches', '5 0 * * *', 'select public.expire_batches()');

-- ---------------------------------------------------------------------------
-- Stock overview and alerts (FR-103)
-- ---------------------------------------------------------------------------

create function public.admin_stock_overview()
returns table (
  product_id uuid,
  slug text,
  product_name text,
  is_published boolean,
  size_code text,
  size_label text,
  category_name text,
  on_hand integer,
  reserved integer,
  available integer,
  low_stock_threshold integer,
  is_low boolean,
  next_expiry date,
  expiring_soon boolean
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_staff();
  return query
  select p.id, p.slug, p.name, p.is_published, i.size_code, s.label, c.name,
         i.on_hand, i.reserved, i.on_hand - i.reserved,
         coalesce(c.low_stock_threshold, st.low_stock_threshold),
         i.on_hand - i.reserved <= coalesce(c.low_stock_threshold, st.low_stock_threshold),
         nx.expires_on,
         nx.expires_on <= current_date + coalesce(c.expiry_alert_days, st.expiry_alert_days)
  from public.inventory_levels i
  join public.products p on p.id = i.product_id
  left join public.product_sizes s on s.product_id = i.product_id and s.code = i.size_code
  left join public.categories c on c.id = p.category_id
  cross join public.store_settings st
  left join lateral (
    select min(b.expires_on) as expires_on from public.stock_batches b
    where b.product_id = i.product_id and b.size_code = i.size_code and b.status = 'available' and b.quantity > 0
  ) nx on true
  order by p.name, s.sort_order nulls first;
end;
$$;

revoke all on function public.admin_stock_overview() from public, anon;
grant execute on function public.admin_stock_overview() to authenticated;

-- Batches to act on: expiring within the alert window, or already expired and still holding units.
create function public.admin_expiring_batches()
returns table (
  batch_id uuid,
  product_id uuid,
  product_name text,
  size_code text,
  size_label text,
  batch_code text,
  expires_on date,
  quantity integer,
  status public.batch_status,
  days_left integer
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.require_staff();
  return query
  select b.id, p.id, p.name, b.size_code, s.label, b.batch_code, b.expires_on, b.quantity, b.status,
         b.expires_on - current_date
  from public.stock_batches b
  join public.products p on p.id = b.product_id
  left join public.product_sizes s on s.product_id = b.product_id and s.code = b.size_code
  left join public.categories c on c.id = p.category_id
  cross join public.store_settings st
  where b.quantity > 0 and b.expires_on is not null and (
    b.status = 'expired'
    or (b.status = 'available' and b.expires_on <= current_date + coalesce(c.expiry_alert_days, st.expiry_alert_days))
  )
  order by b.expires_on, p.name;
end;
$$;

revoke all on function public.admin_expiring_batches() from public, anon;
grant execute on function public.admin_expiring_batches() to authenticated;

